// The shape rules that say a function is no component. scripts/weekly.py `exclusion` applies the same rules to RDT's
// entries; both read src/component-shape.json and both run the cases of tests/fixtures/component-shape-cases.json
// (scripts/test_component_shape.py), so they cannot drift apart.
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import { nonComponentReason, type ShapeProp } from '../src/component-shape.ts'

interface Case {
  why: string
  name: string
  file: string
  props: Record<string, { parent?: string; type: string }>
  expected: string | null
}

const cases: Case[] = JSON.parse(
  readFileSync(join(import.meta.dirname, 'fixtures', 'component-shape-cases.json'), 'utf8'),
)

const shapeProps = (props: Case['props']) =>
  new Map<string, ShapeProp>(Object.entries(props).map(([name, p]) => [name, { path: p.parent, type: () => p.type }]))

describe('nonComponentReason', () => {
  it.each(cases)('$why ($name)', ({ name, file, props, expected }) => {
    expect(nonComponentReason(name, file, shapeProps(props)) ?? null).toBe(expected)
  })

  it('reads a prop type only when the rules before it leave the function undecided', () => {
    expect.hasAssertions()
    let read = 0
    const props = new Map<string, ShapeProp>([
      [
        'x',
        {
          path: '/r/src/a.tsx',
          type: () => {
            read++
            return 'string'
          },
        },
      ],
    ])

    expect(nonComponentReason('useA', '/r/src/a.tsx', props)).toBe('hook')
    expect(read).toBe(0)
    expect(nonComponentReason('A', '/r/src/a.tsx', props)).toBeUndefined()
    expect(read).toBe(1)
  })
})
"""Tests that the weekly's `exclusion` and the oracle's `nonComponentReason` (apps/oracle/src/component-shape.ts) are one
rule: both read apps/oracle/src/component-shape.json, and both run the cases of
apps/oracle/tests/fixtures/component-shape-cases.json (apps/oracle/tests/component-shape.test.ts is the other half)."""
import json
import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import weekly

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ORACLE = os.path.join(ROOT, 'apps', 'oracle')

with open(os.path.join(ORACLE, 'tests', 'fixtures', 'component-shape-cases.json')) as f:
    CASES = json.load(f)


class SharedRules(unittest.TestCase):
    def test_every_case_gets_the_reason_the_oracle_gets(self):
        for case in CASES:
            with self.subTest(case['why']):
                comp = {'name': case['name'], 'file': case['file'], 'props': case['props']}
                self.assertEqual(weekly.exclusion(comp), case['expected'])

    def test_the_cases_cover_every_reason(self):
        self.assertEqual({c['expected'] for c in CASES} - {None},
                         {'lib_members', 'hook', 'context_value', 'not_jsx', 'promise_props'})

    def test_the_oracle_reads_the_same_patterns_file(self):
        with open(os.path.join(ORACLE, 'src', 'component-shape.ts')) as f:
            source = f.read()
        self.assertIn("new URL('component-shape.json', import.meta.url)", source)
        self.assertEqual(weekly.SHAPE['libFile'], weekly.LIB_FILE.pattern)
        self.assertEqual(weekly.SHAPE['hook'], weekly.HOOK.pattern)


if __name__ == '__main__':
    unittest.main()

