// Scores one tool (Caliper, react-docgen-typescript or react-docgen) against the checker over the same universe of props,
// so the three are held to the same rules. Pure: nothing here talks to the checker or reads a file.
//
// The universe is every own prop the checker finds on a candidate component export (React's inherited DOM attributes,
// `ref` and `key` are not part of it, nor are the functions whose shape says they are no component, src/component-shape.ts;
// src/oracle.ts and src/tool-universe.ts filter them). A tool's prop is `listed` when the tool reports it, and gets
// the same verdict the oracle gives Caliper (src/oracle-compare.ts); otherwise it is `missing`, for one of three
// reasons, and counted by where the checker says the prop is declared.
import { compare, VERDICTS, type Norm, type Verdict } from './oracle-compare.ts'

/** Where a prop the tool does not list is declared, by the checker's first declaration. */
export const STRATA = ['same_file', 'other_project_file', 'dependency', 'unknown'] as const
export type Stratum = (typeof STRATA)[number]

/** Why a tool does not list a prop: it reports no such component, the tool threw on the component's file, it reports
 * the component but not that prop, or it lists the prop only as a member of an inherited layer it collapsed
 * (Caliper's `inheritance`, which is a deliberate choice, not an omission). */
export const REASONS = ['component', 'failed_file', 'prop', 'collapsed'] as const
export type Reason = (typeof REASONS)[number]

/** One prop the checker finds, with the checker's type already reduced to a `Norm`. */
export interface UniverseProp {
  /** The component, as the tools are matched to it: file and normalised name. */
  component: string
  prop: string
  stratum: Stratum
  checker: Norm
}

/** What a tool reports for a universe prop: its type as a `Norm`, or why it has none. */
export type Reported = Norm | Reason

export interface ToolScore {
  /** Props the checker finds on the components of the universe. */
  universe: number
  listed: number
  missing: number
  verdicts: Record<Verdict, number>
  /** Identical or spelled, of the whole universe: a prop the tool omits counts against it. */
  agree_universe: number
  /** Identical or spelled, of the props the tool lists. */
  agree_listed: number
  /** Wrong, of the props the tool lists. */
  wrong_listed: number
  missing_by_stratum: Record<Stratum, number>
  missing_by_reason: Record<Reason, number>
  /** Components with at least one prop in the universe, and how many of them the tool reports at all. */
  components: number
  components_found: number
  /** The first few props of each kind the tool gets wrong or less precise, to review the adapters by. */
  examples: Record<'wrong' | 'less precise', { component: string; prop: string; tool: Norm; checker: Norm }[]>
}

const EXAMPLES = 8

const isReason = (value: Reported): value is Reason => typeof value === 'string'
const rate = (n: number, of: number) => (of === 0 ? 0 : n / of)

/** `pick` says what the tool reports for one universe prop. */
export function scoreTool<T extends UniverseProp>(universe: readonly T[], pick: (u: T) => Reported): ToolScore {
  const verdicts = Object.fromEntries(VERDICTS.map((v) => [v, 0])) as Record<Verdict, number>
  const byStratum = Object.fromEntries(STRATA.map((s) => [s, 0])) as Record<Stratum, number>
  const byReason = Object.fromEntries(REASONS.map((r) => [r, 0])) as Record<Reason, number>
  const components = new Set<string>()
  const found = new Set<string>()
  const examples: ToolScore['examples'] = { wrong: [], 'less precise': [] }
  let listed = 0
  for (const u of universe) {
    components.add(u.component)
    const reported = pick(u)
    // A component is found when any of its props is not missing for want of the component itself.
    if (!isReason(reported) || (reported !== 'component' && reported !== 'failed_file')) found.add(u.component)
    if (isReason(reported)) {
      byReason[reported]++
      // A collapsed layer is a choice, not an omission, so it has no stratum.
      if (reported !== 'collapsed') byStratum[u.stratum]++
      continue
    }
    listed++
    const verdict = compare(reported, u.checker)
    verdicts[verdict]++
    if ((verdict === 'wrong' || verdict === 'less precise') && examples[verdict].length < EXAMPLES) {
      examples[verdict].push({
        component: u.component.replace('\0', ' '),
        prop: u.prop,
        tool: reported,
        checker: u.checker,
      })
    }
  }
  const agree = verdicts.identical + verdicts.spelled
  return {
    universe: universe.length,
    listed,
    missing: universe.length - listed,
    verdicts,
    agree_universe: rate(agree, universe.length),
    agree_listed: rate(agree, listed),
    wrong_listed: rate(verdicts.wrong, listed),
    missing_by_stratum: byStratum,
    missing_by_reason: byReason,
    components: components.size,
    components_found: found.size,
    examples,
  }
}

/** Like `scoreTool`, over the components the tool reports only: a prop of a component the tool does not report at all
 * (`component`) is left out, so a function the checker takes for a component and the tool rightly ignores does not
 * count against it. This is the universe of the weekly headline: what a reader of the tool's output is shown. */
export function scoreReported<T extends UniverseProp>(universe: readonly T[], pick: (u: T) => Reported): ToolScore {
  return scoreTool(
    universe.filter((u) => pick(u) !== 'component'),
    pick,
  )
}
// The two methods' answers made into one reference, and a tool's prop type scored against it. Pure: nothing here talks
// to the checker or reads a file.
//
// Method A is the checker's type (src/oracle-checker.ts), method B the type the declaration writes
// (src/reference-declared.ts). They are held to the existing comparison (src/oracle-compare.ts), B as the "tool" and A as
// the "checker": identical or spelled is agreement, B looser than A is B saying less (so A stands alone), and B
// contradicting A is a contest a person settles.
import { compare, type Norm, type Verdict } from './oracle-compare.ts'

/** Which methods stand behind a reference. */
export type Basis = 'both' | 'checker' | 'declaration'

export type Reference =
  // `why` says why one method stands alone: the other abstained, or wrote a looser type than the checker's.
  | { kind: 'agreed'; basis: Basis; norm: Norm; why?: 'abstained' | 'looser' }
  | { kind: 'contested'; checker: Norm; declared: Norm }
  | { kind: 'none' }

/** What a prop's reference looks like to a reader, apart from the types themselves. */
export type Outcome = 'correct' | 'less precise' | 'wrong' | 'contested' | 'no reference' | 'layer' | 'missing'

export const OUTCOMES: Outcome[] = ['correct', 'less precise', 'wrong', 'contested', 'no reference', 'layer', 'missing']

export interface Scored {
  outcome: Outcome
  /** For `correct`, `less precise` and `wrong`: which methods stand behind the verdict. */
  basis?: Basis
  /** For `contested`: the method the tool agrees with, when it agrees with exactly one. */
  leans?: 'checker' | 'declaration'
}

/** A declared type with every name it mentions given itself as its alias, which is how `compare` takes a name for the
 * type it stands for. Where the declaration stands alone the checker could not resolve the name (an unresolved import),
 * so a tool that gives the same name matches it exactly; `compare` would read it as less precise. */
function named(n: Norm): Norm {
  switch (n.k) {
    case 'name': {
      return { ...n, alias: n.name }
    }
    case 'union':
    case 'intersection': {
      return { ...n, members: n.members.map((m) => named(m)) }
    }
    case 'array': {
      return { ...n, element: named(n.element) }
    }
    case 'tuple': {
      return { ...n, elements: n.elements.map((e) => named(e)) }
    }
    case 'function': {
      return {
        ...n,
        params: n.params.map((p) => ({ ...p, type: named(p.type) })),
        returns: named(n.returns),
      }
    }
    default: {
      return n
    }
  }
}

/** Whether a type mentions a name, which is a type this side cannot see into. */
function mentionsName(n: Norm): boolean {
  switch (n.k) {
    case 'name': {
      return true
    }
    case 'union':
    case 'intersection': {
      return n.members.some((m) => mentionsName(m))
    }
    case 'array': {
      return mentionsName(n.element)
    }
    case 'tuple': {
      return n.elements.some((e) => mentionsName(e))
    }
    case 'function': {
      return n.params.some((p) => mentionsName(p.type)) || mentionsName(n.returns)
    }
    default: {
      return false
    }
  }
}

/** A type the checker has nothing to say with: an error, `any`, or a top-level `unknown`. */
const uninformative = (n: Norm) => n.k === 'error' || (n.k === 'prim' && (n.name === 'any' || n.name === 'unknown'))

const AGREE = new Set<Verdict>(['identical', 'spelled'])
const agrees = (verdict: Verdict) => AGREE.has(verdict)

/** One reference from method A (always has a type) and method B (absent when it abstained). */
export function reference(checker: Norm, declared: Norm | undefined): Reference {
  const hasA = !uninformative(checker)
  if (declared === undefined) {
    return hasA ? { kind: 'agreed', basis: 'checker', norm: checker, why: 'abstained' } : { kind: 'none' }
  }
  if (!hasA) return { kind: 'agreed', basis: 'declaration', norm: named(declared), why: 'abstained' }
  const verdict = compare(declared, checker)
  if (agrees(verdict)) return { kind: 'agreed', basis: 'both', norm: checker }
  // The declaration is looser than the checker's type (a name or an unbound parameter the checker evaluated): B said less.
  if (verdict === 'less precise') return { kind: 'agreed', basis: 'checker', norm: checker, why: 'looser' }
  return { kind: 'contested', checker, declared }
}

/** One tool prop type against a reference. `tool` is absent when the tool does not list the prop; `layered` says a
 * collapsed layer's member list names it, which surfaces the prop without a type to judge. */
export function score(tool: Norm | undefined, ref: Reference, layered: boolean): Scored {
  if (tool === undefined) return { outcome: layered ? 'layer' : 'missing' }
  if (ref.kind === 'none') return { outcome: 'no reference' }
  if (ref.kind === 'contested') {
    const vsChecker = agrees(compare(tool, ref.checker))
    const vsDeclared = agrees(compare(tool, ref.declared))
    if (vsChecker === vsDeclared) return { outcome: 'contested', leans: undefined }
    return { outcome: 'contested', leans: vsChecker ? 'checker' : 'declaration' }
  }
  const verdict = compare(tool, ref.norm)
  if (verdict === 'checker any/error') return { outcome: 'no reference' }
  if (agrees(verdict)) return { outcome: 'correct', basis: ref.basis }
  // A declaration standing alone names types it cannot see into, so a mismatch with one is not proof of a wrong type.
  const blind = ref.basis === 'declaration' && mentionsName(ref.norm)
  return { outcome: verdict === 'less precise' || blind ? 'less precise' : 'wrong', basis: ref.basis }
}
// The deterministic construct suite's pure half (apps/oracle/construct-suite/README.md): which fixtures exist, the verdict
// one of Caliper's props earns against its golden, and the check of the expectations file. Nothing here runs the checker
// or Caliper, so tests/construct-suite.test.ts can pin it without either.
import { readdirSync, readFileSync, realpathSync } from 'node:fs'
import { join } from 'node:path'
import { caliperNorm } from './caliper-norm.ts'
import { pathOfExport, exportPathKey, type ComponentExport } from './component-join.ts'
import { compare, type Norm, type Verdict } from './oracle-compare.ts'

/** The prop every fixture states its type through. */
export const PROP = 'p'

/** What the suite says about a row: the comparison's verdict, plus the two cases it cannot make. `opaque with marker`
 * is a type Caliper left unevaluated and said so (`degradedBy`); `missing` is a prop Caliper did not list. */
export type RowVerdict = Verdict | 'opaque with marker' | 'missing'

export const GREEN: RowVerdict[] = ['identical', 'spelled']

/** Best to worst. A row whose verdict moved down this list got worse; up, better. `checker any/error` is a fixture
 * problem (the golden has no type), ranked last so it never reads as an improvement. */
export const ORDER: RowVerdict[] = [
  'identical',
  'spelled',
  'opaque with marker',
  'less precise',
  'wrong',
  'missing',
  'checker any/error',
]

/** What `--check` and the test read back from `<name>.golden.json`. */
export interface Golden {
  /** The checker's type of prop `p`, normalized by src/oracle-checker.ts. */
  checker: Norm
  /** `checker.typeToString` of the same type, for the reader of a diff. */
  text: string
}

/** One row: a component of a fixture file. A file holds one row (`Row`, exported as `Row`) unless it lists its
 * components (`componentsOf`). */
export interface Fixture {
  /** `<family>/<NN>-<slug>`, or `<family>/<NN>-<slug>#<component>` in a file of several components: the row id the
   * expectations file keys on. */
  id: string
  /** The fixture's absolute path. */
  file: string
  /** The golden's absolute path, next to the fixture: `<NN>-<slug>.golden.json`, or `<NN>-<slug>.<component>.golden.json`. */
  golden: string
  /** The component's display name in Caliper's output. */
  component: string
  /** How the module exports it: the export name (`default` for the default export), then the properties of the export
   * a sub-component is attached to (`['default', 'Item']` for `Menu.Item = Item; export default Menu`). */
  exportPath: string[]
}

const FIXTURE = /^\d{2}-[a-z0-9][a-z0-9-]*\.tsx$/
const COMPONENTS = /^\/\/ components:(.*)$/m

/** A fixture of several components lists them in a comment, each as `<display name>=<export path>`:
 * `// components: Item=default.Item Menu=default`. Undefined for a fixture of one `Row`. */
export function componentsOf(source: string): { component: string; exportPath: string[] }[] | undefined {
  const line = COMPONENTS.exec(source)?.[1]
  if (line === undefined) return undefined
  return line
    .trim()
    .split(/\s+/)
    .map((entry) => {
      const [component, path] = entry.split('=')
      if (!component || !path) throw new Error(`"${entry}": a listed component is <display name>=<export path>`)
      return { component, exportPath: path.split('.') }
    })
}

/** Every row of every `<family>/<NN>-<slug>.tsx` under `dir`, sorted by id. A `.tsx` whose name breaks the pattern is
 * an error, not a row that quietly never runs. */
export function listFixtures(dir: string): Fixture[] {
  const fixtures: Fixture[] = []
  for (const family of readdirSync(dir, { withFileTypes: true })) {
    if (!family.isDirectory()) continue
    for (const entry of readdirSync(join(dir, family.name))) {
      if (!entry.endsWith('.tsx')) continue
      if (!FIXTURE.test(entry)) {
        throw new Error(`${family.name}/${entry}: a fixture is named <NN>-<slug>.tsx (lowercase)`)
      }
      const file = join(dir, family.name, entry)
      const id = `${family.name}/${entry.replace(/\.tsx$/, '')}`
      const listed = componentsOf(readFileSync(file, 'utf8'))
      if (listed === undefined) {
        fixtures.push({
          id,
          file,
          golden: file.replace(/\.tsx$/, '.golden.json'),
          component: 'Row',
          exportPath: ['Row'],
        })
        continue
      }
      for (const { component, exportPath } of listed) {
        fixtures.push({
          id: `${id}#${component}`,
          file,
          golden: file.replace(/\.tsx$/, `.${component}.golden.json`),
          component,
          exportPath,
        })
      }
    }
  }
  return fixtures.toSorted((a, b) => (a.id < b.id ? -1 : 1))
}

/** Where Caliper's component for a row is, keyed by `rowKey`: the file and the way its module exports it, the same on
 * both sides, never the display name that two components of a file can share. */
export const rowKey = (file: string, exportedAs: readonly string[]): string => exportPathKey(file, exportedAs)

/** The `rowKey` of each way the module exports one of Caliper's components. */
export function rowKeysOf(component: { filePath: string; exports: ComponentExport[] }): string[] {
  const file = realpathSync(component.filePath)
  return component.exports.map((e) => rowKey(file, pathOfExport(e)))
}

/** The verdict for Caliper's prop against the golden. A prop with `degradedBy` that is only `less precise` is an
 * `opaque with marker`: Caliper said it did not evaluate the type. A `wrong` prop stays wrong with or without a marker. */
export function rowVerdict(prop: { type: unknown; degradedBy?: unknown } | undefined, golden: Golden): RowVerdict {
  if (prop === undefined) return 'missing'
  const verdict = compare(caliperNorm(prop.type), golden.checker)
  const marked = Array.isArray(prop.degradedBy) && prop.degradedBy.length > 0
  return marked && verdict === 'less precise' ? 'opaque with marker' : verdict
}

export interface Expectation {
  /** The verdicts the row may have; the test fails on any other. */
  verdicts: RowVerdict[]
  /** Why Caliper falls short of the checker here. Present exactly on a documented gap. */
  gap?: string
  /** checker-expectations.json only: why the checker path's answer is accepted although its verdict ranks below the
   * structural path's for the same row (see `againstStructural` in src/construct-checker-run.ts). */
  improvement?: string
}

/** Problems with the expectations against the fixtures; empty when they agree. */
export function expectationProblems(ids: string[], rows: Record<string, Expectation>): string[] {
  const problems: string[] = []
  for (const id of ids) {
    const row = rows[id]
    if (row === undefined) {
      problems.push(`${id}: no entry in expectations.json`)
      continue
    }
    if (!Array.isArray(row.verdicts) || row.verdicts.length === 0) {
      problems.push(`${id}: "verdicts" must list at least one verdict`)
      continue
    }
    const unknown = row.verdicts.filter((v) => !ORDER.includes(v))
    if (unknown.length > 0) problems.push(`${id}: unknown verdict ${unknown.join(', ')}`)
    const green = row.verdicts.every((v) => GREEN.includes(v))
    const anyGreen = row.verdicts.some((v) => GREEN.includes(v))
    if (green && row.gap !== undefined) problems.push(`${id}: a green row carries no "gap"`)
    if (!green && anyGreen) {
  caliper: any
  /** The checker and its normaliser (src/oracle-checker.ts). */
  checker: any
  checkerNorm: (type: any) => Norm
  rdt?: ToolDump
  rdg?: ToolDump
}

/** What the universe left out as no component: the functions and props, in all and by the rule that decided it. */
export interface Excluded {
  components: number
  props: number
  by_reason: Partial<Record<ShapeReason, { components: number; props: number }>>
}

type Scores = Record<string, ToolScore & { failed_files?: number }>

/** Collects the universe as components are visited. */
export function universeRecorder(env: Environment) {
  const entries: Entry[] = []
  const rel = (path: string) => relative(env.root, realpathSync(path))
  const scoreOver = (over: readonly Entry[]): Scores => ({
    caliper: scoreTool(over, (u) => u.caliper),
    // Caliper over the components it reports only (src/tool-score.ts `scoreReported`): the weekly headline.
    caliper_reported: scoreReported(over, (u) => u.caliper),
    ...(env.rdt && { rdt: scoreTool(over, (u) => u.rdt!) }),
    ...(env.rdg && { react_docgen: { ...scoreTool(over, (u) => u.rdg!), failed_files: env.rdg.failed.size } }),
  })
  return {
    entries,
    /** `nonComponent` is why the shape rules (src/component-shape.ts) say the function is no component. A function
     * Caliper reports as one stays in the universe whatever its shape: the rules say what Caliper need not list, not what
     * it must not. */
    record({
      own,
      name,
      file,
      matches,
      nonComponent,
    }: {
      own: any[]
      name: string
      file: string
      matches: Match[]
      nonComponent?: ShapeReason
    }) {
      if (own.length === 0) return
      const key = componentKey(rel(file), name)
      const types = env.checker.getTypeOfSymbol(own)
      const [match] = matches.length === 1 ? matches : []
      const excluded = matches.length === 0 ? nonComponent : undefined
      for (const [i, p] of own.entries()) {
        entries.push({
          component: key,
          prop: p.name,
          stratum: stratumOf(p, file),
          checker: env.checkerNorm(types[i]),
          caliper: caliperReported(match, p, env.caliper),
          rdt: env.rdt && reported(env.rdt, { key, prop: p.name }, (t) => rdtNorm(t.typeObject)),
          rdg: env.rdg && reported(env.rdg, { key, prop: p.name }, (t) => rdgNorm(t.tsType)),
          ...(excluded && { nonComponent: excluded }),
        })
      }
    },
    /** One score per tool over the candidate components: the universe without the functions the shape rules exclude.
     * Caliper is scored over the universe as well as over the props both list (`counts`, the verdicts of src/oracle.ts):
     * the two must agree, or the universe is not the one the verdicts were made over. */
    score(counts: Record<Verdict, number>): Scores {
      const scores = scoreOver(entries.filter((e) => !e.nonComponent))
      for (const verdict of VERDICTS) {
        if (scores.caliper.verdicts[verdict] !== counts[verdict]) {
          console.error(
            `warning: Caliper "${verdict}" is ${counts[verdict]} over the shared props, not ${scores.caliper.verdicts[verdict]} over the universe`,
          )
        }
      }
      return scores
    },
    /** The same scores over every function the checker takes for a component: the universe before the shape rules. */
    scoreAll(): Scores {
      return scoreOver(entries)
    },
    /** What the shape rules left out. */
    excluded(): Excluded {
      const components = new Set<string>()
      const byReason = new Map<ShapeReason, { components: Set<string>; props: number }>()
      let props = 0
      for (const e of entries) {
        if (!e.nonComponent) continue
        components.add(e.component)
        props++
        const reason = byReason.get(e.nonComponent) ?? { components: new Set<string>(), props: 0 }
        reason.components.add(e.component)
        reason.props++
        byReason.set(e.nonComponent, reason)
      }
      const by_reason: Excluded['by_reason'] = {}
      for (const reason of SHAPE_REASONS) {
        const found = byReason.get(reason)
        if (found) by_reason[reason] = { components: found.components.size, props: found.props }
      }
      return { components: components.size, props, by_reason }
    },
  }
}

